import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.D1JEzK2q.js";const g=JSON.parse('{"title":"Endpoints Overview","description":"","frontmatter":{},"headers":[],"relativePath":"api/overview.md","filePath":"api/overview.md"}'),c={name:"api/overview.md"};function s(r,t,n,i,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="endpoints-overview" tabindex="-1">Endpoints Overview <a class="header-anchor" href="#endpoints-overview" aria-label="Permalink to &quot;Endpoints Overview {#endpoints-overview}&quot;">​</a></h1><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System {#system}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/health</code></td><td>None</td><td>Liveness only — returns <code>{&quot;status&quot;:&quot;ok&quot;}</code> (no agent list)</td></tr><tr><td><code>GET</code></td><td><code>/status</code></td><td>Admin key or dashboard session¹</td><td>Per-agent stats, legacy/managed sessions, worker pools + heartbeat history</td></tr><tr><td><code>GET</code></td><td><code>/processes</code></td><td>Admin key or dashboard session¹</td><td>Host process tree for the dashboard</td></tr><tr><td><code>GET</code></td><td><code>/knowledge/graph</code></td><td>Admin key or dashboard session¹</td><td>Memory-wiki as <code>{ nodes, edges, demo, scope }</code> for the dashboard <strong>Knowledge base</strong> tab. <code>?scope=shared</code> (default) = the cross-agent Shared KB; <code>?scope=agent:&lt;id&gt;</code> = that agent&#39;s Lane-2 memory (<code>workspace/memory/*.md</code>, id validated against the known-agents allowlist). Computed on-demand (independent of <code>gateway.knowledge.shared.graph</code> and the nightly reindex). Shared scope serves a labelled demo (<code>demo:true</code>) when empty; <code>?demo=off</code> returns the real model; <code>?demo=&lt;N&gt;</code> a synthetic N-node graph for scale testing</td></tr><tr><td><code>GET</code></td><td><code>/knowledge/sources</code></td><td>Admin key or dashboard session¹</td><td>Graph sources for the KB tab&#39;s selector: <code>{ sources: [{ id, label, count }] }</code> — the Shared KB plus every agent with ≥1 Lane-2 memory note</td></tr><tr><td><code>GET</code></td><td><code>/knowledge/note</code></td><td>Admin key or dashboard session¹</td><td>Full Markdown body of one note for the KB tab&#39;s detail section: <code>{ id, scope, path, updated, body }</code> (frontmatter stripped, ≤20 KB; <code>path</code> = gateway-root-relative location, <code>updated</code> = ISO last-modified). <code>?scope=shared|agent:&lt;id&gt;</code> selects the vault (same allowlist guard as <code>/knowledge/graph</code>); <code>?id=&lt;relPath&gt;.md</code> must be a <code>.md</code> path that resolves <strong>inside</strong> that vault (no traversal)</td></tr><tr><td><code>GET</code></td><td><code>/knowledge/dreams</code></td><td>Admin key or dashboard session¹</td><td>Nightly-dreaming audit trail for the <strong>Nightly dreaming</strong> tab: <code>{ runs, agents }</code>, newest-first, parsed from each agent&#39;s <code>.dreaming/DREAMS.md</code> + <code>promotions.jsonl</code> (+ <code>accepted.jsonl</code>). Each proposal carries an <code>index</code> (accept target) and an <code>accepted</code> flag. Bounded (≤200 runs; proposal <code>content</code> truncated)</td></tr><tr><td><code>POST</code></td><td><code>/knowledge/dreams/apply</code></td><td>Admin key or dashboard session¹</td><td>Manually accept <code>propose</code>-mode proposals: applies the selected ops to the agent&#39;s <code>MEMORY.md</code>/<code>USER.md</code> via the <strong>same K4 safe applier</strong> as auto mode (backup + bounded-loss + net-negative + CAS + never-empty; memory-only ⇒ no restart), records them to <code>.dreaming/accepted.jsonl</code> (idempotent), and promotes applied <code>add</code>s to the shared vault when it is <code>auto</code>. Body: <code>{ agentId, ts, indexes?[] }</code> (omit <code>indexes</code> ⇒ whole run). Returns <code>{ applied, skipped, alreadyAccepted, requested, backups }</code>. <code>404</code> unknown agent / no matching run, <code>400</code> bad <code>ts</code>/<code>indexes</code></td></tr><tr><td><code>GET</code></td><td><code>/dashboard</code></td><td>Session cookie¹</td><td>Web UI dashboard (Sessions + Knowledge base + Nightly dreaming tabs; serves the login page when unauthenticated)</td></tr><tr><td><code>POST</code></td><td><code>/dashboard/login</code></td><td>None (validates an admin key)</td><td>Exchange an <strong>admin</strong> API key for an <code>HttpOnly; SameSite=Lax</code> <code>dash_session</code> cookie (8h). Brute-force throttled per IP (<code>429</code> after 10 failed attempts / 5 min)</td></tr><tr><td><code>POST</code></td><td><code>/dashboard/logout</code></td><td>Session cookie</td><td>Revoke the dashboard session and clear the cookie</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/commands</code></td><td>None</td><td>List slash commands available in the chat UI</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/_meta/routes</code></td><td>API key</td><td>Route manifest (every <code>defineRoute</code>-registered endpoint, incl. its CLI noun/verb mapping) — source for the <code>claude-gateway</code> CLI&#39;s codegen and <code>doctor</code> cross-check</td></tr></tbody></table><p>¹ <strong>Auth applies when <code>gateway.api.keys</code> is configured, and requires an <em>admin</em> key</strong> (<code>admin: true</code>). The dashboard/monitoring surface grants cross-agent, host-wide power (session list, process tree, and PTY keystroke injection into any session), so it intentionally requires more than a scoped or write key. &quot;Admin key or dashboard session&quot; accepts an admin API key (<code>X-Api-Key</code> / <code>Authorization: Bearer</code>) <strong>or</strong> the <code>dash_session</code> cookie issued by <code>POST /dashboard/login</code> (which is itself only issued to an admin key). A valid but non-admin key is rejected (<code>401</code>). With <strong>no</strong> keys configured the behavior depends on the bind: on a <strong>loopback</strong> bind (<code>127.0.0.1</code>) they stay open (a keyless local install has no credential to check); on a <strong>non-loopback</strong> bind (<code>0.0.0.0</code> or a real IP) they <strong>fail closed</strong> — <code>/status</code>, <code>/processes</code>, and <code>/dashboard</code> return <code>503</code> until <code>gateway.api.keys</code> is set, so the surface is never exposed unauthenticated to the network. If keys are configured but <strong>none is admin</strong>, the dashboard is inaccessible (login returns <code>401</code>) and a startup warning is emitted. <code>/health</code> stays public in all cases.</p><h2 id="terminal-viewer-cli" tabindex="-1">Terminal viewer (<code>/cli</code>) <a class="header-anchor" href="#terminal-viewer-cli" aria-label="Permalink to &quot;Terminal viewer (`/cli`) {#terminal-viewer-cli}&quot;">​</a></h2><p>See <a href="/claude-gateway/api/terminal.html">Terminal viewer (<code>/cli</code>)</a>.</p><h2 id="agent-api" tabindex="-1">Agent API <a class="header-anchor" href="#agent-api" aria-label="Permalink to &quot;Agent API {#agent-api}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/agents</code></td><td>Key</td><td>List agents accessible by the provided key</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents</code></td><td>Admin</td><td>Create a new agent</td></tr><tr><td><code>PATCH</code></td><td><code>/api/v1/agents/:agentId</code></td><td>Write</td><td>Update agent name, description, model, or allow_tools (<code>connectors</code> needs <strong>Admin</strong>)</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/agents/:agentId</code></td><td>Admin</td><td>Delete an agent</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/messages</code></td><td>Key</td><td>Send a message — sync JSON or SSE stream; supports slash commands</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/greeting</code></td><td>Write</td><td>Stream a proactive welcome from <code>GREETING.md</code> into an existing session (SSE); returns 204 if file absent</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/models</code></td><td>Key</td><td>List available models — live catalog when configured, <code>gateway.models</code> otherwise</td></tr><tr><td><code>PUT</code></td><td><code>/api/v1/agents/:agentId/model</code></td><td>Admin</td><td>Set the active model for an agent</td></tr></tbody></table><h2 id="orchestration-and-voice" tabindex="-1">Orchestration and voice <a class="header-anchor" href="#orchestration-and-voice" aria-label="Permalink to &quot;Orchestration and voice {#orchestration-and-voice}&quot;">​</a></h2><p>See <a href="/claude-gateway/api/orchestration.html#orchestration-and-live-voice">activity polling, scoped task dispatch, voice WebSocket protocol and dashboard fields</a>.</p><h2 id="session-management-api" tabindex="-1">Session Management API <a class="header-anchor" href="#session-management-api" aria-label="Permalink to &quot;Session Management API {#session-management-api}&quot;">​</a></h2><p>Session management operations require <code>chat_id</code> (query param for GET/DELETE, body for POST/PATCH). The resumable stream and orchestration activity/task routes instead use their documented session and principal checks. Sessions are stored at <code>sessions/api-{chat_id}/</code> — symmetric with <code>telegram-{id}</code> and <code>discord-{id}</code>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/sessions</code></td><td>Key</td><td>List API sessions for a <code>chat_id</code></td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/sessions</code></td><td>Key</td><td>Create a new API session (auto-names from prompt)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/sessions/:sessionId/info</code></td><td>Key</td><td>Get session info (name, message count, context %)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/sessions/:sessionId/stream</code></td><td>Key</td><td>Re-attach to the session&#39;s in-flight turn (SSE, resumable from a <code>seq</code> cursor)</td></tr><tr><td><code>PATCH</code></td><td><code>/api/v1/agents/:agentId/sessions/:sessionId</code></td><td>Key</td><td>Rename a session</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/agents/:agentId/sessions/:sessionId</code></td><td>Key</td><td>Delete a session</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/sessions/:sessionId/clear</code></td><td>Key</td><td>Clear session history</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/sessions/:sessionId/compact</code></td><td>Key</td><td>Summarise old history, keep only recent messages</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/sessions/:sessionId/stop</code></td><td>Key</td><td>Interrupt the in-flight turn</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/sessions/:sessionId/restart</code></td><td>Key</td><td>Graceful session restart</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/sessions/:sessionId/attachments</code></td><td>Key</td><td>Register file paths as attachments for the current turn (called internally by <code>api_reply</code> MCP tool)</td></tr></tbody></table><h2 id="workspace-file-api" tabindex="-1">Workspace File API <a class="header-anchor" href="#workspace-file-api" aria-label="Permalink to &quot;Workspace File API {#workspace-file-api}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/files/:filename</code></td><td>Key</td><td>Read a workspace file</td></tr><tr><td><code>PUT</code></td><td><code>/api/v1/agents/:agentId/files/:filename</code></td><td>Write</td><td>Write a workspace file</td></tr></tbody></table><h2 id="telegram-channel-api" tabindex="-1">Telegram Channel API <a class="header-anchor" href="#telegram-channel-api" aria-label="Permalink to &quot;Telegram Channel API {#telegram-channel-api}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/telegram/pending</code></td><td>Admin</td><td>List pending pairing requests (DM + group knocks)</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/telegram/approve</code></td><td>Admin</td><td>Approve a pending pairing by code (kind-aware)</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/telegram/deny</code></td><td>Admin</td><td>Deny a pending pairing by code</td></tr><tr><td><code>PATCH</code></td><td><code>/api/v1/agents/:agentId/telegram/policy</code></td><td>Admin</td><td>Update DM policy, pairing toggle, group policy and/or mention gate</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/telegram/allowlist</code></td><td>Admin</td><td>List allowlisted users</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/agents/:agentId/telegram/allow/:userId</code></td><td>Admin</td><td>Remove a user from the allowlist</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/telegram/group/allowlist</code></td><td>Admin</td><td>List allowlisted group ids</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/agents/:agentId/telegram/group/allow/:groupId</code></td><td>Admin</td><td>Remove a group from the group allowlist</td></tr></tbody></table><h2 id="discord-channel-api" tabindex="-1">Discord Channel API <a class="header-anchor" href="#discord-channel-api" aria-label="Permalink to &quot;Discord Channel API {#discord-channel-api}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/discord/pending</code></td><td>Admin</td><td>List pending pairing requests (DM + guild knocks)</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/discord/approve</code></td><td>Admin</td><td>Approve a pending pairing by code (kind-aware)</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/discord/deny</code></td><td>Admin</td><td>Deny a pending pairing by code</td></tr><tr><td><code>PATCH</code></td><td><code>/api/v1/agents/:agentId/discord/policy</code></td><td>Admin</td><td>Update DM policy, pairing toggle, guild policy and/or mention gate</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/discord/allowlist</code></td><td>Admin</td><td>List allowlisted users</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/agents/:agentId/discord/allow/:userId</code></td><td>Admin</td><td>Remove a user from the allowlist</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/discord/guild/allowlist</code></td><td>Admin</td><td>List allowlisted guild ids</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/agents/:agentId/discord/guild/allow/:guildId</code></td><td>Admin</td><td>Remove a guild from the guild allowlist</td></tr></tbody></table><h2 id="public-webhook-ingress" tabindex="-1">Public Webhook Ingress <a class="header-anchor" href="#public-webhook-ingress" aria-label="Permalink to &quot;Public Webhook Ingress {#public-webhook-ingress}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/webhooks/:app</code></td><td>None (self-authenticating)</td><td>Provider URL-verification probe</td></tr><tr><td><code>GET</code></td><td><code>/webhooks/:app/:agentId</code></td><td>None (self-authenticating)</td><td>Provider URL-verification probe, agent-scoped</td></tr><tr><td><code>POST</code></td><td><code>/webhooks/:app</code></td><td>None (self-authenticating)</td><td>Inbound webhook delivery — first agent with <code>:app</code> configured</td></tr><tr><td><code>POST</code></td><td><code>/webhooks/:app/:agentId</code></td><td>None (self-authenticating)</td><td>Inbound webhook delivery — specific agent</td></tr></tbody></table><h2 id="skill-api" tabindex="-1">Skill API <a class="header-anchor" href="#skill-api" aria-label="Permalink to &quot;Skill API {#skill-api}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/skills</code></td><td>Key</td><td>List all skills (workspace + module + shared)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/skills/:name</code></td><td>Key</td><td>Get a single skill&#39;s content</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/skills</code></td><td>Write</td><td>Create a new skill</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/skills/install</code></td><td>Admin</td><td>Install a skill from a GitHub/raw URL</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/agents/:agentId/skills/:name</code></td><td>Write</td><td>Delete a skill</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/skill-metrics</code></td><td>Key</td><td>Skill self-improvement effectiveness rollup</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/memory-metrics</code></td><td>Key</td><td>Two-lane memory metrics: budget hygiene, archive/shared coverage, dreaming ledger, session-drop invariant</td></tr></tbody></table><h2 id="app-store-api" tabindex="-1">App Store API <a class="header-anchor" href="#app-store-api" aria-label="Permalink to &quot;App Store API {#app-store-api}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/apps/registry</code></td><td>Key</td><td>Fetch community registry (5-min cached)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/apps/registry/:name</code></td><td>Key</td><td>Get versions of a registry app</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/apps</code></td><td>Key</td><td>List installed apps</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/apps/install</code></td><td>Admin</td><td>Start async install → <code>jobId</code></td></tr><tr><td><code>POST</code></td><td><code>/api/v1/apps/inspect</code></td><td>Admin</td><td>Read-only preview of a source → required/generated secrets (no install)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/apps/jobs/:jobId</code></td><td>Key</td><td>Poll install/update job status + logs</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/apps/:name</code></td><td>Key</td><td>Get installed app info</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/apps/:name</code></td><td>Admin</td><td>Uninstall app</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/apps/:name/start</code></td><td>Admin</td><td>Start stopped app</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/apps/:name/stop</code></td><td>Admin</td><td>Stop running app</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/apps/:name/restart</code></td><td>Admin</td><td>Restart app</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/apps/:name/version</code></td><td>Key</td><td>Check installed vs latest version</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/apps/:name/update</code></td><td>Admin</td><td>Start async update with rollback → <code>jobId</code></td></tr><tr><td><code>POST</code></td><td><code>/api/v1/apps/:name/reconfigure</code></td><td>Admin</td><td>Start async env/host-port reconfigure (keeps volumes) → <code>jobId</code></td></tr><tr><td><code>POST</code></td><td><code>/api/v1/apps/housekeeping</code></td><td>Admin</td><td>Docker build-cache &amp; orphan reclaim report (<code>mode:&quot;report&quot;</code>) or safe prune (<code>mode:&quot;prune&quot;</code>)</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/apps/:name/backup</code></td><td>Admin</td><td>Start async snapshot of volumes, bind-mount data dirs &amp; config → <code>jobId</code></td></tr><tr><td><code>POST</code></td><td><code>/api/v1/apps/:name/restore</code></td><td>Admin</td><td>Restore volumes, bind-mount data dirs &amp; config from a backup → <code>jobId</code></td></tr><tr><td><code>GET</code></td><td><code>/api/v1/apps/:name/backups</code></td><td>Key</td><td>List backups (newest first)</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/apps/:name/backups/:id</code></td><td>Admin</td><td>Delete one backup</td></tr><tr><td><code>GET</code></td><td><code>/app/:name/:portName/*</code></td><td>None</td><td>Reverse proxy to installed app</td></tr></tbody></table><p>Backup retention (<code>gateway.appBackup</code>): backups are pruned by the <strong>union</strong> of a count cap and an age cap — a backup is removed when it exceeds <code>retention</code> (keep N newest per app, default <strong>3</strong>, <code>0</code> = unbounded) <strong>or</strong> is older than <code>maxAgeDays</code> (default <strong>30</strong>, <code>0</code> = disabled). Pruning runs after each successful backup and once per day via a scheduler at <code>cleanupHour</code> (0-23, default <code>0</code>) in <code>cleanupTimezone</code> (IANA, default <code>&quot;UTC&quot;</code>, falling back to <code>gateway.timezone</code> when unset or invalid).</p><p>Boot restore (<code>gateway.appRestore</code>): at startup every app stored as <code>running</code> is brought back up in the background. When an image the app needs is missing from the local daemon, the restore first runs <code>docker compose pull --ignore-buildable</code> and <code>docker compose build</code>, each under <code>buildTimeoutMs</code> (default <strong>1800000</strong>, 30 min); it then runs <code>docker compose up -d --wait</code> under <code>waitTimeoutMs</code> (default <strong>180000</strong>, 3 min). The two budgets are separate because a timeout SIGKILLs the compose CLI, and while that only abandons the <em>healthcheck wait</em> once images exist, it <strong>cancels an in-progress build</strong> — so a cold host with no image cache must not have its rebuild bounded by the short wait budget. When the images are already present both cold-start steps are skipped entirely, so a warm reboot is unaffected. Any non-numeric, non-finite or non-positive value falls back to the default. See <code>restoreError</code> under <code>GET /api/v1/apps</code>.</p><h2 id="connectors-api" tabindex="-1">Connectors API <a class="header-anchor" href="#connectors-api" aria-label="Permalink to &quot;Connectors API {#connectors-api}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/connectors</code></td><td>Key</td><td>List every connector with its connected state</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/connectors/:id/status</code></td><td>Key</td><td>Connected boolean for a single connector (for polling)</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/connectors/:id/connect</code></td><td>Admin</td><td>Store a pasted token</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/connectors/:id/oauth/receive</code></td><td>Admin</td><td>Accept an <code>access_token</code> + connector shape pushed by an external control plane</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/connectors/:id</code></td><td>Admin</td><td>Disconnect — clears the credential; removes the whole entry for <code>none</code>/<code>external</code> connectors</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/connectors/custom</code></td><td>Admin</td><td>Add a user-pasted connector</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/connectors/custom/:id/oauth/start</code></td><td>Admin</td><td>Begin the gateway-owned OAuth 2.1 + PKCE sign-in → <code>authorizeUrl</code></td></tr><tr><td><code>GET</code></td><td><code>/oauth/mcp/callback</code></td><td>None (single-use <code>state</code>)</td><td>OAuth redirect target — the provider sends the end user&#39;s own browser here</td></tr></tbody></table><h2 id="cron-api" tabindex="-1">Cron API <a class="header-anchor" href="#cron-api" aria-label="Permalink to &quot;Cron API {#cron-api}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/crons</code></td><td>Key</td><td>List jobs (filtered to key&#39;s accessible agents)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/crons/status</code></td><td>Key</td><td>Scheduler status (total, enabled, running)</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/crons</code></td><td>Key</td><td>Create a new job</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/crons/:id</code></td><td>Key</td><td>Get a single job</td></tr><tr><td><code>PUT</code></td><td><code>/api/v1/crons/:id</code></td><td>Key</td><td>Update a job</td></tr><tr><td><code>DELETE</code></td><td><code>/api/v1/crons/:id</code></td><td>Key</td><td>Delete a job</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/crons/:id/run</code></td><td>Key</td><td>Trigger a job manually</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/crons/:id/runs</code></td><td>Key</td><td>Get run history (last 20 by default)</td></tr></tbody></table><h2 id="chat-history-api" tabindex="-1">Chat History API <a class="header-anchor" href="#chat-history-api" aria-label="Permalink to &quot;Chat History API {#chat-history-api}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/v1/agents/sessions</code></td><td>Admin</td><td>List all sessions across all agents (nested by agent)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/chats</code></td><td>Key</td><td>List all chats for an agent</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/chats/:chatId/sessions</code></td><td>Key</td><td>List sessions for a specific chat</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/chats/:chatId/messages</code></td><td>Key</td><td>Paginated message history (cursor-based)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/chats/:chatId/messages/search</code></td><td>Key</td><td>Full-text search across messages (SQLite FTS5)</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/chats/:chatId/messages/active-days</code></td><td>Key</td><td>Distinct local calendar days with &gt;= 1 message in a window (jump-to-date dots)</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/chats/:chatId/sessions/:sessionId/messages</code></td><td>Key</td><td>Inject a message into an existing channel session (SSE stream)</td></tr></tbody></table><h2 id="media-api" tabindex="-1">Media API <a class="header-anchor" href="#media-api" aria-label="Permalink to &quot;Media API {#media-api}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Auth</th><th>Description</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/agents/:agentId/media</code></td><td>Key</td><td>Upload a media file (image/* or PDF) — returns <code>mediaPath</code></td></tr><tr><td><code>GET</code></td><td><code>/api/v1/agents/:agentId/media/*</code></td><td>Key</td><td>Serve a media file by path</td></tr></tbody></table><h2 id="file-share-bridge-api" tabindex="-1">File Share Bridge API <a class="header-anchor" href="#file-share-bridge-api" aria-label="Permalink to &quot;File Share Bridge API {#file-share-bridge-api}&quot;">​</a></h2><p>See <a href="/claude-gateway/api/shares.html">File Share Bridge API</a>.</p><h2 id="pty-shell-api" tabindex="-1">PTY Shell API <a class="header-anchor" href="#pty-shell-api" aria-label="Permalink to &quot;PTY Shell API {#pty-shell-api}&quot;">​</a></h2><p>See <a href="/claude-gateway/api/pty.html">PTY Shell API</a>.</p>',39)])])}const m=e(c,[["render",s]]);export{g as __pageData,m as default};
